45	/** @brief 行跨度换算成 EPIC 要的"像素数"（本产品画布固定 RGB565 = 2 B/px）。 */
46	#define MYVENDOR_EPIC_PX_PER_ROW(stride)   ((uint16_t)((stride) / sizeof(uint16_t)))
47	
48	/*
49	 * RGB565 → RGB888 的**位复制**展开（EPIC 的填充色分量是 RGB888）。
50	 *
51	 * 位复制在"截断"与"四舍五入"两种硬件做法下都能精确回读原来的 5/6 位：
52	 *   r5=31 → r8=(31<<3)|(31>>2)=255 → 255>>3=31；四舍五入 31*31/255=31 ✓
53	 *   g6=63 → g8=(63<<2)|(63>>4)=255 → 255>>2=63；四舍五入 63*63/255=63 ✓
54	 * 而直接 `r5<<3`（低位补 0）在四舍五入的做法下会掉到 30，所以不用它。
55	 * ⚠ LVGL 的 `lv_color_to_epic_color()` 是把 5/6 位**原样**塞进 8 位字段的，
56	 * 与本文件约定不同；谁对由 vmap_blit.c 的开机自检（fill 用例）实测。
57	 */
58	static uint8_t epic_expand5(uint16_t v)
59	{
60	  return (uint8_t)((v << 3) | (v >> 2));
61	}
62	
63	static uint8_t epic_expand6(uint16_t v)
64	{
65	  return (uint8_t)((v << 2) | (v >> 4));
66	}
67	
68	static uint8_t * epic_at(void * buf, uint32_t stride, int32_t x, int32_t y)
69	{
70	  return (uint8_t *)buf + (size_t)y * stride + (size_t)x * sizeof(uint16_t);
71	}
