78	/**
79	 * @brief  EPIC 写完目的矩形后，把**被写到的那些行**从 CPU 缓存里作废。
80	 * @param  rect_tl 目的矩形左上角像素指针（本层约定：`out.data` 就是它）。
81	 * @param  stride   目的缓冲的行跨度（字节）。
82	 * @param  w, h     矩形宽高（像素）。
83	 *
84	 * @details 为什么必须做（2026-09-27，PSRAM 写回审计的 G1）：EPIC 是**绕过 CPU 缓存**
85	 *          直接写内存的 master。CPU 只要在那些像素上有缓存行（写过或读过就会留下），
86	 *          读回来就是**旧像素**。目的缓冲在 PSRAM（画布 0x60E00000）时这条一定成立 ——
87	 *          PSRAM 是 cacheable，且产品默认已是写回（`CONFIG_MYVENDOR_PSRAM_CACHE_WB=y`）。
88	 *
89	 * @warning ① **只作废矩形内的行**，不要图省事整层作废 —— 矩形外的像素 CPU 可能正握着刚
90	 *          写的数据（写回模式下是脏行），一并作废就是**丢数据**；
91	 * @warning ② 只在缓冲位于 PSRAM 时做（判据同芯片的 `IS_DCACHED_RAM`：地址 ≥ 0x60000000；
92	 *          SRAM 不在缓存范围内，做了纯属浪费）；
93	 * @warning ③ 依赖"包装返回时硬件必定已停"这个既有约定（见文件头：NuttX 上的
94	 *          `HAL_EPIC_*Start*` 是 polling 版）—— 换成 `_IT` 版就必须挪到回调里。
95	 */
96	static void epic_invalidate_rect_rows(const void * rect_tl, uint32_t stride,
97	  int32_t w, int32_t h)
98	{
99	  int32_t i;
100	
101	  if ((uintptr_t)rect_tl < 0x60000000u || w <= 0 || h <= 0)
102	    {
103	      return;
104	    }
105	
106	  for (i = 0; i < h; i++)
107	    {
108	      uintptr_t row = (uintptr_t)rect_tl + (uintptr_t)i * stride;
109	
110	      up_invalidate_dcache(row, row + (uintptr_t)w * sizeof(uint16_t));
111	    }
112	}
113	
114	/* EPIC 等待超时 ⇒ 本次当作**失败**返回：上层 vmap_blit 的 CPU 兜底会把这一块
115	 * 重做一遍，所以既不会卡死、也不会在半搬完的画布上留错像素（用户 2026-09-26）。 */
116	extern volatile uint32_t g_epic_wait_timeouts;
117	
118	static bool epic_result(uint32_t wt_before, bool hal_ok, const char * what)
119	{
120	  if (g_epic_wait_timeouts != wt_before)
121	    {
