131	bool myvendor_epic_copy(uint16_t * dst_buf, uint32_t dst_stride, int32_t dx,
132	  int32_t dy, const uint16_t * src_buf, uint32_t src_stride, int32_t sx,
133	  int32_t sy, int32_t w, int32_t h)
134	{
135	  const uint32_t wt_before = g_epic_wait_timeouts;
136	  EPIC_LayerConfigTypeDef in;
137	  EPIC_LayerConfigTypeDef out;
138	
139	  if (lv_epic_get_handle() == NULL)
140	    {
141	      return false;
142	    }
143	
144	  /* HAL 明确要求这两个偏移非负（`EPIC_ConfigLayer()` 里判负即 HAL_ERROR）。 */
145	  if (sx < 0 || sy < 0 || dx < 0 || dy < 0)
146	    {
147	      return false;
148	    }
149	
150	  /* 坐标/尺寸寄存器是 16 位，且上层另有溢出检查（EPIC_COORDINATES_MAX）。 */
151	  if (sx + w > EPIC_COORDINATES_MAX || sy + h > EPIC_COORDINATES_MAX
152	      || dx + w > EPIC_COORDINATES_MAX || dy + h > EPIC_COORDINATES_MAX)
153	    {
154	      return false;
155	    }
156	
157	  /*
158	   * ⚠ 这里的摆法是**踩过坑**的，改动前先看这段：
159	   *
160	   * EPIC 的混合语义是"**图层内容留在它自己的画布位置**"：对画布点 (X,Y)，
161	   * 它读 `in.data[X - in.x_offset]` 写到 `out.data[X - out.x_offset]`
162	   * （见 `EPIC_ConfigOutputLayer()` 里 `offset = (y0 - output->y_offset) *
163	   * output->total_width + (x0 - output->x_offset)` 那一段）。
164	   * 也就是说：**平移必须体现在 data 指针上，不能体现在 x_offset/y_offset 上**
165	   * —— 后者会让内容停在原地（那就成了"原地混合"，不是搬运）。
166	   * 实测（2026-09-25 开机自检）：把位移放进 offset 时，九个方向**全部**与 CPU
167	   * 不一致（EPIC 只在两个矩形的交集里写，落点还差了一个位移）。
168	   *
169	   * 所以：
170	   *   - 两个 `data` 各自指向自己矩形的左上角像素（位移在这里）；
171	   *   - 两个 `x_offset/y_offset` **取同一个值**（用目的矩形的坐标），
172	   *     这样图层矩形与输出矩形完全重合 ⇒ 交集 = 整个矩形，
173	   *     EPIC 才会对每一列都读一次源；否则不重合的那部分会被 `continue` 掉
174	   *     （`EPIC_ConfigBlendEx()` 里"输入与输出不相交就跳过该层"）。
175	   *   - `total_width` = 各自的行跨度（像素），矩形尺寸另给。
176	   *   - 单输入层 + 不透明 alpha（`LayerConfigInit` 置 255）⇒ 逐位拷贝。
177	   */
178	  HAL_EPIC_LayerConfigInit(&in);
179	  in.data = epic_at((void *)src_buf, src_stride, sx, sy);
180	  in.color_mode = EPIC_COLOR_RGB565;
181	  in.width = (uint16_t)w;
182	  in.height = (uint16_t)h;
183	  in.x_offset = (int16_t)dx;
184	  in.y_offset = (int16_t)dy;
185	  in.total_width = MYVENDOR_EPIC_PX_PER_ROW(src_stride);
186	
187	  HAL_EPIC_LayerConfigInit(&out);
188	  out.data = epic_at((void *)dst_buf, dst_stride, dx, dy);
189	  out.color_mode = EPIC_COLOR_RGB565;
190	  out.width = (uint16_t)w;
191	  out.height = (uint16_t)h;
192	  out.x_offset = (int16_t)dx;
193	  out.y_offset = (int16_t)dy;
194	  out.total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
195	
196	  bool ok = epic_result(wt_before, (lv_epic_blend(&in, 1, &out)) == HAL_OK, "copy");
197	
198	  if (ok)
199	    {
200	      /* 目的侧作废（见 epic_invalidate_rect_rows 的说明）；out.data 就是矩形左上角
201	       * —— 这条摆放约定在 2026-09-25 的开机自检里钉过（见上面那段 ⚠ 注释）。 */
202	      epic_invalidate_rect_rows(out.data, dst_stride, w, h);
203	    }
204	
205	  return ok;
206	}
