208	bool myvendor_epic_fill(uint16_t * dst_buf, uint32_t dst_stride, int32_t x,
209	  int32_t y, int32_t w, int32_t h, uint16_t color565)
210	{
211	  const uint32_t wt_before = g_epic_wait_timeouts;
212	  EPIC_LayerConfigTypeDef out;
213	
214	  if (lv_epic_get_handle() == NULL)
215	    {
216	      return false;
217	    }
218	
219	  if (x < 0 || y < 0)
220	    {
221	      return false;
222	    }
223	
224	  if (x + w > EPIC_COORDINATES_MAX || y + h > EPIC_COORDINATES_MAX)
225	    {
226	      return false;
227	    }
228	
229	  HAL_EPIC_LayerConfigInit(&out);
230	  out.data = epic_at((void *)dst_buf, dst_stride, x, y);
231	  out.color_mode = EPIC_COLOR_RGB565;
232	  out.width = (uint16_t)w;
233	  out.height = (uint16_t)h;
234	  out.x_offset = (int16_t)x;
235	  out.y_offset = (int16_t)y;
236	  out.total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
237	  out.color_en = true;
238	  out.color_r = epic_expand5((uint16_t)((color565 >> 11) & 0x1fu));
239	  out.color_g = epic_expand6((uint16_t)((color565 >> 5) & 0x3fu));
240	  out.color_b = epic_expand5((uint16_t)(color565 & 0x1fu));
241	
242	  /* 输入层数 = 0 ⇒ `lv_epic_fill()` 走 HAL_EPIC_fill(NULL, 0, &out) == HAL_OK; 这条路径 */
243	  bool ok = epic_result(wt_before, (lv_epic_fill(NULL, 0, &out)) == HAL_OK, "fill");
244	
245	  if (ok)
246	    {
247	      epic_invalidate_rect_rows(out.data, dst_stride, w, h);
248	    }
249	
250	  return ok;
251	}
