223	/** Return with sinus of an angle
224	 *
225	 * @param angle in degree
226	 * @return sinus of 'angle'. sin(-90) = -32767, sin(90) = 32767
227	 */
228	int16_t EPIC_TrigoSin(int16_t angle)
229	{
230	    int16_t ret = 0;
231	
232	    while (angle < 0) angle += 360;
233	    while (angle >= 360) angle -= 360;
234	
235	    if (angle < 90)
236	    {
237	        ret = sin0_90_table[angle];
238	    }
239	    else if ((angle >= 90) && (angle < 180))
240	    {
241	        angle = 180 - angle;
242	        ret   = sin0_90_table[angle];
243	    }
244	    else if ((angle >= 180) && (angle < 270))
245	    {
246	        angle = angle - 180;
247	        ret   = -sin0_90_table[angle];
248	    }
249	    else
250	    {
251	        /*angle >=270*/
252	        angle = 360 - angle;
253	        ret   = -sin0_90_table[angle];
254	    }
255	
256	    return ret;
257	}
