5587	        {
5588	            if (IS_ALPHA_MASK_LAYER(&input[i]))
5589	            {
5590	                return HAL_ERROR; //Mask layer not support transform
5591	            }
5592	#if defined(SF32LB58X)
5593	            else if ((int8_t)EPIC_LAYER_IDX_2 == cur_fix_depth_layer) //L2 support transfrom
5594	            {
5595	                epic_layer[i]       = cur_fix_depth_layer;
5596	                cur_fix_depth_layer--;
5597	            }
5598	#endif /* SF32LB55X */
5599	            else if (video_layer_valid)
5600	            {
5601	                epic_layer[i] = EPIC_LAYER_IDX_VL;
5602	                video_layer_valid = 0;
5603	                *vl_depth = cur_fix_depth_layer + 1;
5604	            }
5605	            else
5606	                return HAL_ERROR;
5607	        }
5608	        else if (IS_ALPHA_MASK_LAYER(&input[i]))
5609	        {
5610	#ifndef SF32LB55X
5611	            //Only one mask layer supported.
5612	            if (++mask_num > 1)  return HAL_ERROR;
5613	            //Mask layer should not at bottom
5614	            if (0 == i)  return HAL_ERROR;
5615	
5616	            epic_layer[i] = EPIC_SPECIAL_LAYER_MASK;
5617	#else
5618	            return HAL_ERROR;
5619	#endif /* SF32LB55X */
5620	        }
5621	        else
5622	        {
5623	            if ((video_layer_valid) &&
5624	                    ((cur_fix_depth_layer < (int8_t)EPIC_LAYER_IDX_0)
5625	
5626	                     /*VL has independent read bus for low speed memory,
5627	                       and last layer always is framebuffer with no transform requirement
5628	                       */
5629	                     || (1 == i)
5630	                    ))
5631	            {
5632	                epic_layer[i] = EPIC_LAYER_IDX_VL;
5633	                video_layer_valid = 0;
5634	                *vl_depth = cur_fix_depth_layer + 1;
5635	            }
5636	            else if (cur_fix_depth_layer >= (int8_t)EPIC_LAYER_IDX_0)
5637	            {
5638	                epic_layer[i]       = cur_fix_depth_layer;
5639	                cur_fix_depth_layer--;
5640	            }
5641	            else
5642	            {
5643	                return HAL_ERROR; //No avaliable layer
5644	            }
5645	        }
5646	
5647	        if (IS_EZIP_COLOR_MODE(input[i].color_mode))
5648	        {
5649	#ifdef HAL_EZIP_MODULE_ENABLED
5650	            if (++ezip_num > 1) return HAL_ERROR;
5651	#else
5652	            return HAL_ERROR;
5653	#endif
5654	        }
5655	
5656	        if (IS_YUV_COLOR_MODE(input[i].color_mode))
5657	        {
5658	#if defined(SF32LB56X)||defined(SF32LB52X)
5659	            if (++yuv_num > 1) return HAL_ERROR;
5660	#else
5661	            return HAL_ERROR;
5662	#endif /* SF32LB56X */
5663	        }
5664	    }
5665	
5666	    return HAL_OK;
5667	}
