5670	/**
5671	 * @brief
5672	 * @param epic -
5673	 * @param input - layers's blending data
5674	 * @param alpha - layers's alpha
5675	 * @param transform_cfg - layers's transfrom configuration
5676	 * @param layer_num - layers number
5677	 * @return
5678	 */
5679	static HAL_StatusTypeDef EPIC_ConfigBlendEx(EPIC_HandleTypeDef *epic,

5679	static HAL_StatusTypeDef EPIC_ConfigBlendEx(EPIC_HandleTypeDef *epic,
5680	        EPIC_BlendingDataType *input,
5681	        uint8_t *alpha,
5682	        EPIC_TransformCfgTypeDef *transform_cfg, uint8_t layer_num)
5683	{
5684	    HAL_StatusTypeDef ret;
5685	    uint32_t i;
5686	    uint8_t video_layer_depth;
5687	
5688	    EPIC_LAYER_IDX epic_layer[MAX_EPIC_LAYER];
5689	    EPIC_TransformResultDef trans_result[MAX_EPIC_LAYER];
5690	
5691	    uint32_t ezip_layer_idx = UINT32_MAX;
5692	
5693	    uint8_t input_layer_num = layer_num - 1;
5694	    EPIC_BlendingDataType *output = &input[layer_num - 1];
5695	#ifdef EPIC_SUPPORT_DITHER
5696	    uint32_t output_bit_mask, input_bit_mask = 0;
5697	    uint8_t layer_dither_level = 0;
5698	#endif /* EPIC_SUPPORT_DITHER */
5699	
5700	    EPIC_PRINTF("\r\n EPIC_ConfigBlendEx \r\n");
5701	    //1.Choose EPIC layer for each input
5702	    ret = EPIC_ChooseLayer(input, transform_cfg, input_layer_num, epic_layer, &video_layer_depth);
5703	    if (HAL_OK != ret)
5704	    {
5705	        return ret;
5706	    }
5707	
5708	    //2.Transfrom layer to update other layer's coordinates
5709	    for (i = 0; i < input_layer_num; i++)
5710	    {
5711	        EPIC_TransResultInit(&trans_result[i], &input[i]);
5712	
5713	        EPIC_PRINTF("%d: EPIC_layer idx %d \n", i, epic_layer[i]);
5714	
5715	        EPIC_ClipLayerSrcByOutput(&input[i], &transform_cfg[i], output, &trans_result[i]);
5716	        if (IS_NEED_TRANSFROM_LAYER(&input[i], &transform_cfg[i]))
5717	        {
5718	            ret = EPIC_TransformVideoLayer(epic->Instance, epic_layer[i],
5719	                                           &transform_cfg[i], &input[i], output, &trans_result[i]);
5720	            if (HAL_OK != ret)
5721	            {
5722	                return ret;
5723	            }
5724	            if (!EPIC_CalcIntersectArea(&input[i], output, NULL))
5725	            {
5726	                input[i].width  = 0;//Inactive this layer.
5727	                input[i].height = 0;
5728	            }
5729	
5730	        }
5731	        EPIC_MakeAllLayerCoordValidEx(input, input_layer_num + 1); //+1 for output layer
5732	    }
5733	
5734	    //3.Config EPIC layer
5735	    for (i = 0; i < input_layer_num; i++)
5736	    {
5737	        if (!EPIC_CalcIntersectArea(&input[i], output, NULL))
5738	        {
5739	            //No intersect skip layer
5740	            continue;
5741	        }
5742	        else if (IS_NEED_TRANSFROM_LAYER(&input[i], &transform_cfg[i])
5743	                 || (EPIC_LAYER_IDX_VL == epic_layer[i])
5744	#ifndef SF32LB55X
5745	                 || (EPIC_LAYER_IDX_2 == epic_layer[i])
5746	#endif /* SF32LB55X */
5747	                )
5748	        {
5749	            ret = EPIC_ConfigVideoLayer(epic, epic_layer[i], &trans_result[i], &input[i], alpha[i], video_layer_depth);
5750	        }
5751	        else if (IS_ALPHA_MASK_LAYER(&input[i]))
5752	        {
5753	            HAL_ASSERT(i > 0);
5754	            //Mask next layer
5755	            ret = EPIC_ConfigMaskLayer(epic, epic_layer[i - 1], &input[i]);
5756	        }
5757	        else
5758	        {
5759	            ret = EPIC_ConfigLayer(epic, epic_layer[i], &input[i], true, alpha[i]);
5760	        }
5761	#ifdef EPIC_SUPPORT_DITHER
5762	        if (!IS_EZIP_COLOR_MODE(input[i].color_mode))
5763	        {
5764	            input_bit_mask |= EPIC_GetColorBitMask(input[i].color_mode, input[i].ax_mode);
5765	            layer_dither_level = HAL_MAX(layer_dither_level, input[i].dither_level);
5766	        }
5767	#endif /* EPIC_SUPPORT_DITHER */
5768	
5769	        if (HAL_OK != ret)
5770	        {
5771	            return ret;
5772	        }
5773	
5774	
5775	        if (IS_EZIP_COLOR_MODE(input[i].color_mode))
5776	        {
5777	            ezip_layer_idx = i;
5778	        }
5779	    }
5780	
5781	    ret = EPIC_ConfigOutputLayerEx(epic, input, input_layer_num, output);
5782	    if (HAL_OK != ret)
5783	    {
5784	        return ret;
5785	    }
5786	
5787	#ifdef EPIC_SUPPORT_DITHER
5788	    output_bit_mask = EPIC_GetColorBitMask(output->color_mode, ALPHA_BLEND_INVALID);
5789	#endif /* EPIC_SUPPORT_DITHER */
5790	#ifdef HAL_EZIP_MODULE_ENABLED
5791	    if (ezip_layer_idx != UINT32_MAX)
5792	    {
5793	        ret = EPIC_ConfigEzipDec(epic, &input[ezip_layer_idx], output, &trans_result[ezip_layer_idx]);
5794	    }
5795	#endif
5796	#ifdef EPIC_SUPPORT_DITHER
5797	    EPIC_ConfigDither(epic, (input_bit_mask & (~output_bit_mask)), layer_dither_level);
5798	#endif /* EPIC_SUPPORT_DITHER */
5799	
5800	    return ret;
5801	}
