135	uint32_t lv_epic_setup_layers(EPIC_LayerConfigTypeDef * epic_bg_layer,
136	                              EPIC_LayerConfigTypeDef * epic_output_layer,
137	                              lv_draw_task_t * draw_task,
138	                              const lv_area_t * coords)
139	{
140	    lv_layer_t * layer = draw_task->target_layer;
141	    uint16_t dest_total_width;
142	
143	    lv_area_t blend_area;
144	    if(!lv_area_intersect(&blend_area, coords, &draw_task->clip_area)) {
145	        return 1; /* Fully clipped, nothing to do */
146	    }
147	
148	    if(!lv_area_intersect(&blend_area, &blend_area, &layer->buf_area)) {
149	        return 1; /* Fully clipped, nothing to do */
150	    }
151	
152	    lv_color_format_t dest_cf = layer->color_format;
153	    dest_total_width = layer->draw_buf ? lv_epic_stride_to_width(layer->draw_buf->header.stride, dest_cf) :
154	                       lv_area_get_width(&layer->buf_area);
155	
156	    /* Setup background layer */
157	    HAL_EPIC_LayerConfigInit(epic_bg_layer);
158	    epic_bg_layer->color_en = false;
159	    epic_bg_layer->data = (uint8_t *)lv_draw_layer_go_to_xy(layer, 0, 0);
160	    epic_bg_layer->color_mode = lv_img_cf_to_epic_cf(dest_cf);
161	    epic_bg_layer->width = lv_area_get_width(&layer->buf_area);
162	    epic_bg_layer->total_width = dest_total_width;
163	    epic_bg_layer->height = lv_area_get_height(&layer->buf_area);
164	    epic_bg_layer->x_offset = layer->buf_area.x1;
165	    epic_bg_layer->y_offset = layer->buf_area.y1;
166	
167	    /* Setup output layer */
168	    memcpy(epic_output_layer, epic_bg_layer, sizeof(*epic_output_layer));
169	    epic_output_layer->width = lv_area_get_width(&blend_area);
170	    epic_output_layer->height = lv_area_get_height(&blend_area);
171	    epic_output_layer->x_offset = blend_area.x1;
172	    epic_output_layer->y_offset = blend_area.y1;
173	    epic_output_layer->data = (uint8_t *)lv_draw_layer_go_to_xy(layer,
174	                                                                blend_area.x1 - layer->buf_area.x1,
175	                                                                blend_area.y1 - layer->buf_area.y1);
176	
177	    LV_ASSERT((epic_output_layer->height * epic_output_layer->width) <= EPIC_MAX_PIXELS);
178	
179	    return 0; /* Success */
180	}
