211	    if(LV_COLOR_FORMAT_RGB565A8 == cf) return true;
212	#endif
213	
214	#ifdef EPIC_SUPPORT_A4
215	    if(LV_COLOR_FORMAT_A4 == cf) return true;
216	#endif
217	
218	#ifdef EPIC_SUPPORT_A2
219	    if(LV_COLOR_FORMAT_A2 == cf) return true;
220	#endif
221	
222	#ifdef EPIC_SUPPORT_L8
