135	{
136	    LV_PROFILER_DRAW_BEGIN;
137	    lv_draw_dsc_base_t * base_dsc = t->draw_dsc;
138	    base_dsc->layer = layer;
139	
140	    lv_draw_global_info_t * info = &_draw_info;
141	
142	    /*Send LV_EVENT_DRAW_TASK_ADDED and dispatch only on the "main" draw_task
143	     *and not on the draw tasks added in the event.
144	     *Sending LV_EVENT_DRAW_TASK_ADDED events might cause recursive event sends and besides
145	     *dispatching might remove the "main" draw task while it's still being used in the event*/
146	
147	    if(info->task_running == false) {
148	        if(base_dsc->obj && lv_obj_has_flag(base_dsc->obj, LV_OBJ_FLAG_SEND_DRAW_TASK_EVENTS)) {
149	            info->task_running = true;
150	            lv_obj_send_event(base_dsc->obj, LV_EVENT_DRAW_TASK_ADDED, t);
151	            info->task_running = false;
152	        }
153	
154	        /*Let the draw units set their preference score*/
155	        t->preference_score = 100;
156	        t->preferred_draw_unit_id = 0;
157	        lv_draw_unit_t * u = info->unit_head;
158	        while(u) {
159	            if(u->evaluate_cb) {
160	                LV_PROFILER_DRAW_BEGIN_TAG("evaluate_cb");
