168	        if(t->preferred_draw_unit_id == LV_DRAW_UNIT_NONE) {
169	            LV_LOG_WARN("the draw task was not taken by any units");
170	            t->state = LV_DRAW_TASK_STATE_FINISHED;
171	        }
172	        else {
173	            lv_draw_dispatch();
174	        }
175	    }
176	    else {
177	        /*Let the draw units set their preference score*/
178	        t->preference_score = 100;
179	        t->preferred_draw_unit_id = 0;
180	        lv_draw_unit_t * u = info->unit_head;
